const grid=document.querySelector('.products'); if(!grid)return;
const euro=n=>new Intl.NumberFormat('fi-FI',{style:'currency',currency:'EUR',maximumFractionDigits:0}).format(n);
const images={};
grid.querySelectorAll('.product').forEach(card=>{const name=card.querySelector('h3')?.textContent.trim();const src=card.querySelector('img')?.src;if(name&&src)images[name]=src;});
const collectionName={spyder:'Spyder',novemillimetri:'Novemillimetri',cuscinetto:'Cuscinetto',shock:'Shock ABS'};
const shortText=p=>{
 if(p.collection==='shock') return 'Sporttinen 42 mm:n Shock ABS -kello, läpinäkyvä monikerroksinen kellotaulu ja pimeässä hohtavat indeksit. '+(p.price===275?'Teräsranneke.':'Kumiranneke.');
 if(p.collection==='novemillimetri') return 'Ohut ja viimeistelty titaanikello italialaisella urheilullisella muotoilulla.';
 if(p.collection==='cuscinetto') return 'Näyttävä Cuscinetto-malli, jossa yhdistyvät tunnistettava muotoilu ja huolitellut yksityiskohdat.';
 return 'Urheilullinen Spyder-kronografi rohkealla värityksellä ja tunnistettavalla muotoilulla.';
};
grid.innerHTML=catalog.map(p=>{
 const img=p.image||images[p.name];
 const status=p.soldOut;
 return '<article class="product" data-category="'+p.collection+'" data-product-id="'+p.id+'" data-sold-out="'+(status?'true':'false')+'">'+
   '<a class="product-photo" href="'+(p.productUrl||'#yhteys')+'" aria-label="Tutustu '+p.name+' -malliin">'+(img?'<img src="'+img+'" alt="Tonino Lamborghini '+p.name+'">':'<div class="catalog-placeholder"><span>TONINO<br>LAMBORGHINI</span><small>TIMEPIECES</small></div>')+'</a>'+
   '<h3>'+p.name+'</h3>'+
   '<div class="price">'+euro(p.price)+'</div>'+
   '<p class="product-summary">'+shortText(p)+'</p>'+
   '<details class="product-details"><summary>Tekniset tiedot</summary><div class="product-details-body">'+
   (p.sku?'<p><strong>Tuotekoodi:</strong> '+p.sku+'</p>':'')+
   (p.movement?'<p><strong>Koneisto:</strong> '+p.movement+'</p>':'')+
   (p.case?'<p><strong>Kuori ja lasi:</strong> '+p.case+'</p>':'')+
   (p.dimensions?'<p><strong>Mitat ja paino:</strong> '+p.dimensions+'</p>':'')+
   (p.water?'<p><strong>Vesitiiviys:</strong> '+p.water+'</p>':'')+
   (p.strap?'<p><strong>Ranneke:</strong> '+p.strap+'</p>':'')+
   '</div></details>'+
   ''+
   '</article>';
}).join('');

const collectionShowcase=document.createElement('div');
collectionShowcase.className='collection-showcase';
collectionShowcase.innerHTML='<div class="collection-showcase-head"><span>FOUR DISTINCT COLLECTIONS</span><h3>Neljä mallistoa. Neljä omaa tyyliä.</h3><p>Valitse mallisto ja tutustu sen kelloihin.</p></div><div class="collection-showcase-grid">'+[
 {id:'spyder',name:'Spyder',desc:'Urheilullinen ja näyttävä'},
 {id:'novemillimetri',name:'Novemillimetri',desc:'Ohut ja viimeistelty'},
 {id:'cuscinetto',name:'Cuscinetto',desc:'Omaleimaista muotoilua'},
 {id:'shock',name:'Shock ABS',desc:'Sporttinen ja rennompi'}
].map(item=>{
 const product=catalog.find(p=>p.collection===item.id&&p.image);
 const image=product?product.image:'';
 return '<button class="collection-tile" type="button" data-collection-filter="'+item.id+'">'+
 (image?'<span class="collection-tile-image"><img src="'+image+'" alt=""></span>':'<span class="collection-tile-image collection-tile-empty">TL</span>')+
 '<span class="collection-tile-copy"><strong>'+item.name+'</strong><small>'+item.desc+'</small><em>Katso mallisto →</em></span></button>';
}).join('')+'</div>';
filters.insertAdjacentElement('afterend',collectionShowcase);
collectionShowcase.querySelectorAll('[data-collection-filter]').forEach(tile=>tile.addEventListener('click',()=>{
 const selected=tile.dataset.collectionFilter;
 const matchingFilter=document.querySelector('.filter[data-filter="'+selected+'"]');
 if(matchingFilter) matchingFilter.click();
 else {
   document.querySelectorAll('.filter').forEach(button=>button.classList.toggle('active',button.dataset.filter===selected));
   document.querySelectorAll('.product').forEach(card=>{card.hidden=card.dataset.category!==selected;});
 }
 grid.scrollIntoView({behavior:'smooth',block:'start'});
}));

const filters=document.querySelector('.filters');filters.innerHTML='<button class="filter active" data-filter="all">Kaikki 68</button><button class="filter" data-filter="spyder">Spyder 39</button><button class="filter" data-filter="novemillimetri">Novemillimetri 8</button><button class="filter" data-filter="cuscinetto">Cuscinetto 11</button><button class="filter" data-filter="shock">Shock ABS 10</button>';
